mapper.insert:
insert into report_evidence_manifest (
    id, report_id, source_wp, source_type, source_ref_digest, schema_version,
    summary_keys_json, redaction_flags_json, evidence_summary_json, created_at
) values (
    #{id}, #{reportId}, #{sourceWp}, #{sourceType}, #{sourceRefDigest}, #{schemaVersion},
    cast(coalesce(#{summaryKeysJson}, '[]') as jsonb),
    cast(coalesce(#{redactionFlagsJson}, '{}') as jsonb),
    cast(coalesce(#{evidenceSummaryJson}, '{}') as jsonb),
    #{createdAt}
)

insert into report_failure_diagnosis (
    id, report_id, status, classification_json, model_invocation_digest, confidence,
    manual_review_required, diagnosis_summary_json, error_code, created_at, updated_at
) values (
    #{id}, #{reportId}, #{status},
    cast(coalesce(#{classificationJson}, '{}') as jsonb),
    #{modelInvocationDigest}, #{confidence}, #{manualReviewRequired},
    cast(coalesce(#{diagnosisSummaryJson}, '{}') as jsonb),
    #{errorCode}, #{createdAt}, #{updatedAt}
)

insert into report_export_manifest (
    id, report_id, export_type, status, schema_version, field_set_version,
    redaction_policy_json, content_digest, aggregate_only, exported_by, exported_at,
    block_reason, created_at
) values (
    #{id}, #{reportId}, #{exportType}, #{status}, #{schemaVersion}, #{fieldSetVersion},
    cast(coalesce(#{redactionPolicyJson}, '{}') as jsonb),
    #{contentDigest}, #{aggregateOnly}, #{exportedBy}, #{exportedAt}, #{blockReason}, #{createdAt}
)

mapper.select:
select 
from report_execution_report
where status = 'GENERATING'
  and updated_at < #{threshold}
order by updated_at asc, id asc
limit #{limit}

select 
from report_defect_draft
where report_id = #{reportId}
  and id = #{draftId}

select 
from report_export_manifest
where report_id = #{reportId}
and export_type = #{exportType}
order by created_at desc, id desc
limit 1

select 
from report_export_manifest
where report_id = #{reportId}
  and id = #{exportId}

select count(*)
from report_export_manifest
where report_id = #{reportId}

select count(*)
from report_defect_draft
where report_id = #{reportId}

select 
from report_execution_report
where project_id = #{projectId}
  and execution_run_id = #{executionRunId}
  and request_key = #{requestKey}
order by created_at asc
limit 1

select 
from report_execution_report

order by generated_at desc nulls last, created_at desc
limit #{query.limit}
offset #{query.offset}

select project_id
from report_execution_report
where id = #{id}
